export const encoder=new TextEncoder;export const decoder=new TextDecoder;const MAX_INT32=2**32;export function concat(...e){const n=e.reduce((e,{length:n})=>e+n,0),t=new Uint8Array(n);let r=0;for(const n of e)t.set(n,r),r+=n.length;return t}function writeUInt32BE(e,n,t){if(n<0||n>=MAX_INT32)throw new RangeError(`value must be >= 0 and <= 4294967295. Received ${n}`);e.set([n>>>24,n>>>16,n>>>8,255&n],t)}export function uint64be(e){const n=Math.floor(e/MAX_INT32),t=e%MAX_INT32,r=new Uint8Array(8);return writeUInt32BE(r,n,0),writeUInt32BE(r,t,4),r}export function uint32be(e){const n=new Uint8Array(4);return writeUInt32BE(n,e),n}export function encode(e){const n=new Uint8Array(e.length);for(let t=0;t<e.length;t++){const r=e.charCodeAt(t);if(r>127)throw new TypeError("non-ASCII string encountered in encode()");n[t]=r}return n}